CREATE TABLE space_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('atelier','studio','archive')), visibility TEXT NOT NULL CHECK(visibility IN ('private','public')));
CREATE TABLE space_user (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES space_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), user_id TEXT NOT NULL, name TEXT NOT NULL, avatar TEXT, role TEXT NOT NULL CHECK(role IN ('author','spectator')));
CREATE TABLE space_collection (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES space_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), collection_id TEXT NOT NULL, name TEXT NOT NULL, addressed_document_id TEXT NOT NULL);
CREATE TABLE space_program (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES space_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), plugin_id TEXT NOT NULL);
CREATE TABLE space_extension (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES space_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), extension_id TEXT NOT NULL, version TEXT NOT NULL, source_uri TEXT NOT NULL, package_hash TEXT NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)));
